-- 11. 상태 이력의 고장 구간 ↔ 비가동 번호 연결
UPDATE equipment_status_history h SET downtime_id = d.downtime_id
FROM downtime_event d
WHERE h.equipment_id = d.equipment_id AND h.started_at = d.started_at AND h.status <> 'R';

COMMIT;
